SELECT 'score_players' AS target, COUNT(DISTINCT `user_id`) AS row_count FROM `score` WHERE `id` IN (SELECT `id` FROM `score` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'))
UNION ALL SELECT 'chart', COUNT(*) FROM `chart` WHERE `sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee')
UNION ALL SELECT 'score', COUNT(*) FROM `score` WHERE `id` IN (SELECT `id` FROM `score` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'))
UNION ALL SELECT 'chart_best', COUNT(*) FROM `chart_best` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee')
UNION ALL SELECT 'replay', COUNT(*) FROM `replay` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee') OR `score_id` IN (SELECT `id` FROM `score` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'))
UNION ALL SELECT 'play_trace', COUNT(*) FROM `play_trace` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee') OR `score_id` IN (SELECT `id` FROM `score` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'))
UNION ALL SELECT 'play_analysis', COUNT(*) FROM `play_analysis` WHERE `trace_id` IN (SELECT `id` FROM `play_trace` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee') OR `score_id` IN (SELECT `id` FROM `score` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'))) OR `pattern_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'
UNION ALL SELECT 'submission_audit', COUNT(*) FROM `submission_audit` WHERE `score_id` IN (SELECT `id` FROM `score` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'))
UNION ALL SELECT 'chart_pattern', COUNT(*) FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' OR `sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee')
UNION ALL SELECT 'table_chart', COUNT(*) FROM `table_chart` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee')
UNION ALL SELECT 'course_chart_kept', COUNT(*) FROM `course_chart` WHERE `chart_sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee') OR `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee'
UNION ALL SELECT 'user_folder_item', COUNT(*) FROM `user_folder_item` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' OR `sha256` IN (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee')
UNION ALL SELECT 'ai_result', COUNT(*) FROM `ai_result` WHERE CAST(`output` AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci LIKE '%f8b3b8ca5b5c5f7be1352b7aae723bee%' OR CAST(`output` AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci LIKE '%架空ユリカゴ%' OR `subject_key` LIKE '%f8b3b8ca5b5c5f7be1352b7aae723bee%' OR EXISTS (SELECT 1 FROM (SELECT `sha256` FROM `chart` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `score` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `chart_sha256` FROM `play_trace` WHERE `chart_md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee' UNION SELECT `sha256` FROM `chart_pattern` WHERE `md5` = 'f8b3b8ca5b5c5f7be1352b7aae723bee') p WHERE CAST(`output` AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', p.`sha256`, '%') OR `subject_key` LIKE CONCAT('%', p.`sha256`, '%'));
